<script setup>
import { computed, ref, watch } from 'vue'
import GadgetArt from './GadgetArt.vue'
import UiIcon from './UiIcon.vue'

const props = defineProps({
  user: { type: Object, default: null },
  ideas: { type: Array, default: () => [] },
  myIdeas: { type: Array, default: () => [] },
  gadgets: { type: Array, default: () => [] },
  busy: { type: Boolean, default: false },
  error: { type: String, default: '' },
  capabilities: { type: Object, default: () => ({ submissions: false }) },
  pendingIdeas: { type: Array, default: () => [] },
  admin: { type: Boolean, default: false },
  initialDraft: { type: Object, default: null },
})
const emit = defineEmits(['submit', 'draft', 'refresh', 'login', 'moderate', 'refresh-admin'])
const section = ref('public')
const name = ref('')
const effect = ref('')
const warning = ref('')
const parentIds = ref([])
const localError = ref('')
const moderationReasons = ref({})
const moderationError = ref('')
const form = ref(null)
watch(() => props.initialDraft, draft => {
  if (!draft || name.value || effect.value || warning.value) return
  name.value = typeof draft.name === 'string' ? draft.name.slice(0, 24) : ''
  effect.value = typeof draft.effect === 'string' ? draft.effect.slice(0, 160) : ''
  warning.value = typeof draft.warning === 'string' ? draft.warning.slice(0, 160) : ''
  parentIds.value = Array.isArray(draft.parentIds) ? draft.parentIds.filter(id => props.gadgets.some(g => g.id === id)).slice(0, 2) : []
}, { immediate: true })
const publicIdeas = computed(() => props.ideas.filter(idea => !idea.status || ['approved', 'accepted', 'published'].includes(idea.status)))
const publishedMine = computed(() => props.myIdeas.filter(idea => ['approved', 'accepted', 'published'].includes(idea.status)))
const open = computed(() => Boolean(props.capabilities.submissions))
const canSubmit = computed(() => Boolean(props.user) && open.value && !props.busy)
const hasDraft = computed(() => Boolean(name.value.trim() || effect.value.trim() || warning.value.trim()))
const statusLabels = { pending: '等待审核', approved: '已收录', accepted: '已收录', published: '已收录', rejected: '待修改', draft: '草稿' }
watch(() => props.admin, admin => { if (!admin && section.value === 'review') section.value = 'public' })
watch(() => props.gadgets, gadgets => { parentIds.value = parentIds.value.filter(id => gadgets.some(gadget => gadget.id === id)) })
function selectParent(id) {
  if (props.busy) return
  localError.value = ''
  if (parentIds.value.includes(id)) parentIds.value = parentIds.value.filter(item => item !== id)
  else if (parentIds.value.length < 2) parentIds.value = [...parentIds.value, id]
  else localError.value = '一次只邀请两件道具。点击已选的道具，就能换一位小伙伴。'
}
function payload() { return { name: name.value.trim(), effect: effect.value.trim(), warning: warning.value.trim(), parentIds: [...parentIds.value] } }
function submit() {
  localError.value = ''
  if (!canSubmit.value || !form.value?.reportValidity()) return
  const idea = payload()
  if (!idea.name || !idea.effect || !idea.warning) { localError.value = '给道具取个名字，再写下效果和乌龙注意事项吧。'; return }
  if (idea.parentIds.length === 1) { localError.value = '合体脑洞需要两件道具；也可以取消选择，提交全新的原创道具。'; return }
  emit('submit', idea)
}
function saveDraft() { if (hasDraft.value && !props.busy) emit('draft', payload()) }
function switchSection(value) { section.value = value; if (value === 'review' && props.admin) emit('refresh-admin') }
function date(value) { const parsed = new Date(value); return value && !Number.isNaN(parsed.getTime()) ? parsed.toLocaleDateString('zh-CN', { timeZone: 'Asia/Shanghai', month: 'numeric', day: 'numeric' }) : '' }
function artwork(idea) { return idea.gadget || idea }
function author(idea) { return idea.authorName || idea.author?.displayName || idea.author?.name || idea.contributorName || '一位口袋朋友' }
function moderate(idea, status) {
  if (!props.admin || props.busy) return
  const reason = (moderationReasons.value[idea.id] || '').trim().slice(0, 160)
  if (status === 'rejected' && !reason) { moderationError.value = '请写一句具体的修改建议，让投稿者知道该怎样把脑洞完善。'; return }
  moderationError.value = ''
  emit('moderate', { id: idea.id, status, reason })
}
</script>

<template>
  <section class="inner-page community-page">
    <div class="page-intro"><span class="eyebrow"><UiIcon name="spark" :size="17" /> 认真收藏每一个不太靠谱的好点子</span><h1>让脑洞，<span class="highlight-word">长出小翅膀</span></h1><p>发明一件道具，把你的奇思妙想放进大家的口袋。</p></div>
    <div class="community-note"><span class="idea-note-icon"><UiIcon name="flask" :size="26" /></span><div><strong>脑洞投稿箱，欢迎奇妙的你。</strong><p>{{ open ? '登录后可投稿，审核通过的原创道具会收录进公共图鉴。' : '投稿箱还在准备中。可以先写下脑洞，等开张后再来分享。' }}</p></div><span class="note-postmark">IDEAS WELCOME<br><i>✧</i></span></div>
    <nav class="community-tabs" aria-label="脑洞收藏分类"><button :class="{active:section==='public'}" :aria-current="section==='public'?'page':undefined" @click="switchSection('public')">大家的奇思妙想 <span>{{ publicIdeas.length }}</span></button><button :class="{active:section==='mine'}" :aria-current="section==='mine'?'page':undefined" @click="switchSection('mine')">我的投稿 <span>{{ myIdeas.length }}</span></button><button v-if="admin" :class="{active:section==='review'}" :aria-current="section==='review'?'page':undefined" @click="switchSection('review')">投稿审核 <span>{{ pendingIdeas.length }}</span></button><button class="refresh-button" :disabled="busy" @click="section==='review' ? emit('refresh-admin') : emit('refresh')"><UiIcon name="shuffle" :size="14" />{{ busy ? '正在翻找…' : '刷新' }}</button></nav>
    <p v-if="error" class="community-error" role="alert"><UiIcon name="info" :size="17" />{{ error }}</p>

    <template v-if="section !== 'review'">
      <div class="community-layout">
        <form ref="form" class="idea-form" @submit.prevent="submit">
          <span class="section-kicker">YOUR NEXT LITTLE INVENTION</span><h2>今天，想发明什么？<span>✧</span></h2><p class="compose-tip">别忘了：一点点乌龙，才是道具的灵魂。</p>
          <label class="idea-field" for="idea-name"><span>给道具取个名字 <small>{{ name.length }} / 24</small></span><input id="idea-name" v-model="name" maxlength="24" placeholder="比如，周一快乐发射器" required :disabled="busy" autocomplete="off"></label>
          <label class="idea-field" for="idea-effect"><span>它能帮上什么忙？ <small>{{ effect.length }} / 160</small></span><textarea id="idea-effect" v-model="effect" maxlength="160" rows="3" placeholder="说说它会怎样解决一件小烦恼…" required :disabled="busy"></textarea></label>
          <label class="idea-field warning-field" for="idea-warning"><span><UiIcon name="info" :size="14" /> 乌龙注意事项 <small>{{ warning.length }} / 160</small></span><textarea id="idea-warning" v-model="warning" maxlength="160" rows="3" placeholder="使用之后，会闹出什么哭笑不得的小意外？" required :disabled="busy"></textarea></label>
          <fieldset v-if="gadgets.length" class="parent-selector"><legend>邀请两件道具来碰个头 <span>可选</span></legend><p>也可以不选，发明一件完全新的小奇妙。</p><div class="parent-grid"><button v-for="gadget in gadgets" :key="gadget.id" type="button" :class="{selected:parentIds.includes(gadget.id)}" :aria-pressed="parentIds.includes(gadget.id)" :disabled="busy" @click="selectParent(gadget.id)"><GadgetArt :kind="gadget.kind" :color="gadget.color" /><span>{{ gadget.name }}</span><i v-if="parentIds.includes(gadget.id)"><UiIcon name="check" :size="12" /></i></button></div><span class="parent-count">已选择 {{ parentIds.length }} / 2 件</span></fieldset>
          <p v-if="localError" class="form-error" role="alert">{{ localError }}</p><button class="primary-button" type="submit" :disabled="!canSubmit"><UiIcon name="spark" :size="18" />{{ busy ? '正在寄出脑洞…' : !open ? '投稿箱即将开张' : !user ? '登录后投递脑洞' : '把脑洞放进口袋' }}<UiIcon name="arrow" :size="18" /></button><div class="draft-actions"><button class="text-button" type="button" :disabled="!hasDraft || busy" @click="saveDraft">先保存这份草稿</button><button v-if="!user" class="text-button" type="button" @click="emit('login')">登录我的口袋 <UiIcon name="arrow" :size="13" /></button></div><p class="originality-note">提交自己的原创点子，避开已有角色、专属名称和他人作品。审核通过后，大家就能遇见你的发明。</p>
        </form>

        <div class="idea-gallery">
          <template v-if="section === 'public'"><div class="gallery-heading"><div><span class="section-kicker">MADE BY POCKET FRIENDS</span><h2>这些脑洞，来自你我。</h2></div><span class="gallery-mark">原创收录</span></div><div v-if="!publicIdeas.length" class="ideas-empty"><span class="empty-doodle"><UiIcon name="pocket" :size="52" /><i>✧</i></span><h3>第一份奇思妙想，还在路上。</h3><p>{{ busy ? '口袋正在翻找大家的脑洞，稍等一会儿。' : open ? '提交一件原创道具，审核通过后，就能在这里与大家见面。' : '脑洞投稿箱即将开放。登录后可投稿，审核通过的点子会收入公共图鉴。' }}</p><span class="empty-handwriting">不靠谱一点，也没关系。</span></div><div v-else class="public-grid"><article v-for="idea in publicIdeas" :key="idea.id" class="public-idea"><div class="community-art" :style="{'--idea-color':artwork(idea).color || '#c6a86a'}"><span class="idea-number">NO.{{ String(artwork(idea).no || 'UGC').replace('NO.','') }}</span><GadgetArt :kind="artwork(idea).kind || 'spark'" :color="artwork(idea).color || '#c6a86a'" /><span class="art-star">✧</span></div><div class="idea-card-copy"><h3>{{ idea.name || artwork(idea).name }}</h3><p class="idea-effect"><UiIcon name="check" :size="14" /><span>{{ idea.effect || artwork(idea).effect }}</span></p><p class="idea-warning"><UiIcon name="info" :size="14" /><span>{{ idea.warning || artwork(idea).warning }}</span></p><footer><span>{{ author(idea) }}</span><span class="contributor-tag"><UiIcon name="star" :size="11" />{{ idea.contributorBadge || '奇妙贡献者' }}</span></footer></div></article></div></template>

          <template v-else><div class="gallery-heading"><div><span class="section-kicker">YOUR IDEAS ARE WORTH KEEPING</span><h2>每个小点子，都认真收好。</h2></div></div><div v-if="publishedMine.length" class="contributor-note"><span><UiIcon name="star" :size="24" /></span><div><strong>奇妙贡献者</strong><p>{{ publishedMine.length }} 件原创道具已收录，谢谢你让口袋更奇妙。</p></div></div><div v-if="!user" class="ideas-empty"><UiIcon name="book" :size="46" /><h3>先认领你的专属口袋。</h3><p>登录后，投稿和审核进展都会好好保存在这里。</p><button class="primary-button" @click="emit('login')">登录查看我的投稿 <UiIcon name="arrow" :size="17" /></button></div><div v-else-if="!myIdeas.length" class="ideas-empty"><UiIcon name="spark" :size="44" /><h3>还没有寄出的小脑洞。</h3><p>先给道具取个名字吧。那些忽然冒出的好点子，都值得留住。</p></div><div v-else class="my-ideas"><article v-for="idea in myIdeas" :key="idea.id" class="my-idea"><header><span class="submission-status" :class="idea.status">{{ statusLabels[idea.status] || '处理中' }}</span><span v-if="idea.createdAt">{{ date(idea.createdAt) }} 投稿</span></header><h3>{{ idea.name }}</h3><p class="idea-effect"><UiIcon name="check" :size="15" /><span>{{ idea.effect }}</span></p><p class="idea-warning"><UiIcon name="info" :size="15" /><span>{{ idea.warning }}</span></p><div v-if="idea.status==='rejected'" class="review-reason"><strong>再完善一点，就更奇妙了</strong><p>{{ idea.reason || idea.reviewReason || idea.moderationReason || '这份脑洞还需要一点调整。欢迎完善原创设定后重新投稿。' }}</p></div><p v-else-if="idea.status==='pending'" class="submission-note">已经收到你的脑洞，正在认真读。审核通过后，它会出现在公共图鉴里。</p><p v-else-if="['approved','accepted','published'].includes(idea.status)" class="submission-note approved-note"><UiIcon name="star" :size="14" />已收录进公共图鉴，你也是奇妙贡献者啦。</p></article></div></template>
        </div>
      </div>
    </template>

    <template v-else-if="admin"><div class="review-heading"><div><span class="section-kicker">A LITTLE CARE FOR EVERY IDEA</span><h2>给每份脑洞，一次认真的回应。</h2><p>检查原创性、道具效果和副作用；退回时留下具体的修改建议。</p></div><span>{{ pendingIdeas.length }} 份待审核</span></div><p v-if="moderationError" class="community-error" role="alert"><UiIcon name="info" :size="16" />{{ moderationError }}</p><div v-if="!pendingIdeas.length" class="ideas-empty review-empty"><UiIcon name="check" :size="44" /><h3>投稿箱已经整理好啦。</h3><p>{{ busy ? '正在查看待审核投稿。' : '新的脑洞到来时，会出现在这里。' }}</p></div><div v-else class="moderation-grid"><article v-for="idea in pendingIdeas" :key="idea.id" class="moderation-card"><header><span>{{ author(idea) }}</span><small>{{ date(idea.createdAt) }}</small></header><h3>{{ idea.name }}</h3><p class="idea-effect"><UiIcon name="check" :size="15" /><span>{{ idea.effect }}</span></p><p class="idea-warning"><UiIcon name="info" :size="15" /><span>{{ idea.warning }}</span></p><p v-if="idea.parentIds?.length" class="review-parents">合体来源：{{ idea.parentIds.map(id=>gadgets.find(gadget=>gadget.id===id)?.name || id).join(' + ') }}</p><label :for="`review-reason-${idea.id}`" class="moderation-field">给投稿者的回复 <span>{{ (moderationReasons[idea.id] || '').length }} / 160</span><textarea :id="`review-reason-${idea.id}`" v-model="moderationReasons[idea.id]" maxlength="160" rows="3" placeholder="需要修改的话，请说清楚哪里还可以完善。" :disabled="busy"></textarea></label><div class="moderation-actions"><button class="review-return" :disabled="busy" @click="moderate(idea,'rejected')">退回并给出建议</button><button class="primary-button" :disabled="busy" @click="moderate(idea,'approved')"><UiIcon name="check" :size="16" />审核通过，收录</button></div></article></div></template>
  </section>
</template>

<style scoped>
